#!/usr/bin/env bash
# THE ACTUAL ROOT CAUSE of everything since the last several fixes, finally
# visible thanks to those exact fixes (agent.log + threading.excepthook):
#
#     ValueError: signal only works in main thread of the main interpreter
#
# agent/main.py called signal.signal(SIGTERM/SIGINT, ...) unconditionally.
# That only works on the main thread of the main interpreter - and the
# Windows service wrapper (service_files/windows/opslab_agent_service.py)
# deliberately runs agent_run() on a background thread, specifically so
# SvcStop() can signal a clean shutdown via a Win32 event instead of
# relying on OS signals (which behave differently for services). Every
# single time the real OpsLabAgent SERVICE started, this raised
# IMMEDIATELY - killing the whole function silently right after logging
# "No kiosk_start_command configured yet" and before ever starting any of
# the four polling threads (heartbeat/config/update/command) - which is
# exactly why nothing ever progressed past registration: those threads
# were simply never created.
#
# This was invisible for so long specifically because EVERY foreground/
# console "... service\opslab_agent_service.py run" test throughout this
# whole debugging session worked perfectly - that path calls agent_run()
# directly on the MAIN thread, where signal.signal() is completely legal.
# The real installed service has been broken this way this entire time;
# console mode being reliable actively hid it.
#
# Fixed: only register OS signal handlers when actually running on the
# main thread (threading.current_thread() is threading.main_thread()) -
# skip gracefully otherwise, which is exactly correct for the service
# case, since SvcStop already signals external_stop_event directly and
# never needed OS-level signal delivery in the first place.
#
# Verified by directly reproducing the exact ValueError on a background
# thread with the old code, then confirming the fixed version skips
# cleanly there while still registering normally on the main thread
# (preserving the existing console/systemd behavior exactly as before).
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt service_files; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

echo "==> Extracting fixed agent/ into this repo"
TMP_EXTRACT="$(mktemp -d)"
base64 -d > "$TMP_EXTRACT/opslab-agent.tar.gz" << 'AGENT_TAR_EOF_MARKER'

AGENT_TAR_EOF_MARKER
tar -xzf "$TMP_EXTRACT/opslab-agent.tar.gz" -C "$TMP_EXTRACT"

if ! grep -q "threading.current_thread() is threading.main_thread()" "$TMP_EXTRACT/agent/main.py"; then
    echo "    ERROR: fix not found in the extracted agent payload!"
    rm -rf "$TMP_EXTRACT"
    exit 1
fi

rm -f agent/config.py.bak
cp -f "$TMP_EXTRACT/agent/"*.py agent/
echo "    Updated agent/*.py in this repo."

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz (served by /install.ps1)"
cp -f "$TMP_EXTRACT/opslab-agent.tar.gz" app/static/installers/opslab-agent.tar.gz
rm -rf "$TMP_EXTRACT"

echo "==> Verifying"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    served agent tarball is readable"

echo ""
echo "Done. On Ewan, re-enroll ONE more time:"
echo "    irm https://kiosksys.opslabsystems.cloud/install.ps1 -OutFile install.ps1; .\\install.ps1 -Token <fresh-token> -AdminUrl https://kiosksys.opslabsystems.cloud"
echo ""
echo "This should be the real fix - the service should now actually reach"
echo "'Agent running as instance ... Press Ctrl+C to stop.' in agent.log, start"
echo "polling, download+install v1.0.1, and come up fully working, with no"
echo "foreground console session ever needed again."
